#!/bin/bash
cd "$(dirname "$0")/.."
ST="Mobile game UI icon sheet in a cute chunky cartoon style matching the reference (thick dark-brown outlines, bright saturated flat colors, soft cel shading, glossy highlights), like a polished casual mobile RPG interface. Transparent background. Exactly 4 rows x 5 columns of separate icons, evenly spaced on a grid, each centered in its cell, no overlap. No text, no letters, no numbers."
gen(){ name=$1; prompt=$2
  url=$(higgsfield generate create gpt_image_2_6 --quality high --resolution 2k --aspect_ratio 5:4 --background transparent --image-references art-gen/style-ref.png --prompt "$prompt" --wait 2>&1 | grep -Eo 'https://[^ ]+\.(png|webp)' | tail -1)
  [ -n "$url" ] && curl -sSL -o art-gen/raw/$name.png "$url" && echo "$(date +%H:%M) OK $name $url" >> art-gen/log.txt && echo "OK $name" || echo "FAIL $name"; }
gen icons_ui2 "$ST Icons in reading order: 1 glossy red heart, 2 steel sword pointing up-right, 3 blue and silver round shield, 4 yellow lightning bolt, 5 red and white bullseye target, 6 orange starburst explosion, 7 two orange fists bumping, 8 two blue curved arrows forming a circle, 9 white sneaker with little wings, 10 red blood drop with tiny white fangs, 11 golden padlock (closed), 12 green round badge with white check mark, 13 flat light-grey silhouette of a sword, 14 flat light-grey silhouette of a boxing glove, 15 flat light-grey silhouette of a pendant necklace, 16 flat light-grey silhouette of a karate jacket, 17 flat light-grey silhouette of a boot, 18 flat light-grey silhouette of a ring, 19 purple music note, 20 blue speaker with sound waves." &
gen icons_ui3 "$ST Icons in reading order: 1 film clapperboard, 2 smartphone with a curved arrow, 3 small bar chart, 4 red round button with white X, 5 green round button with white plus, 6 orange hourglass, 7 cartoon skull, 8 two crossed swords, 9 yellow fast-forward double arrow, 10 rolled treasure map, 11 purple speech bubble with a question mark shape, 12 small house with a pink heart, 13 folded paper note with a red wax seal, 14 green medical cross, 15 white sparkle star cluster, 16 orange flame, 17 blue open book with a glowing page, 18 purple karate belt tied in a knot, 19 golden key, 20 red alarm exclamation badge." &
wait
